    if isinstance(spec, type):
        if not isinstance(target, spec):
            raise TypeMatchError(type(target), spec)
        return target
    elif isinstance(spec, (list, tuple)):
        if not isinstance(target, (list, tuple)):
            raise TypeMatchError(type(target), type(spec))
        if len(target) != len(spec):
            raise MatchError("length mismatch: expected {0}, got {1}",
                             len(spec), len(target))
        result = []
        for i, (t, s) in enumerate(zip(target, spec)):
            try:
                result.append(scope[glom](t, s, chain_child(scope)))
            except GlomError as ge:
                raise MatchError("index {0} did not match: {1!r}", i, ge)
        return type(spec)(result)
    elif isinstance(spec, dict):
        return _handle_dict(target, spec, scope)
    elif isinstance(spec, (set, frozenset)):
        if not isinstance(target, (set, frozenset)):
            raise TypeMatchError(type(target), type(spec))
        if len(target) != len(spec):
            raise MatchError("length mismatch: expected {0}, got {1}",
                             len(spec), len(target))
